package com.hengaikj.ai.config;
import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import org.springframework.context.annotation.*; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.data.redis.serializer.*;
@Configuration public class RedisConfig { @Bean public RedisTemplate<String,Object> redisTemplate(RedisConnectionFactory f){ObjectMapper om=new ObjectMapper();om.registerModule(new JavaTimeModule());om.activateDefaultTyping(om.getPolymorphicTypeValidator(),ObjectMapper.DefaultTyping.NON_FINAL);RedisTemplate<String,Object> t=new RedisTemplate<>();t.setConnectionFactory(f);var key=new StringRedisSerializer();var val=new GenericJackson2JsonRedisSerializer(om);t.setKeySerializer(key);t.setHashKeySerializer(key);t.setValueSerializer(val);t.setHashValueSerializer(val);t.afterPropertiesSet();return t;} }
